      local count=best>=4 and best or 1
      if best>=4 then
        flags=flags+2^bit items[#items+1]=string.char(math.floor(distance/256),distance%256,best-3)
      else items[#items+1]=data:sub(i,i) end
      for pos=i,i+count-1 do
